import { Config, Effect, Layer, ServiceMap } from "effect"

export class ArtifactLinks extends ServiceMap.Service<
  ArtifactLinks,
  {
    readonly downloadUrl: (artifactId: string) => string
    readonly previewUrl: (artifactId: string) => string
  }
>()("@workspace/artifacts/ArtifactLinks") {}

const make = Effect.gen(function*() {
  const baseUrl = yield* Config.string("ARTIFACT_PUBLIC_URL")
  const tenant = yield* Config.string("ARTIFACT_TENANT")

  const buildUrl = (artifactId: string, action: string): string => {
    const url = new URL(
      `artifacts/${encodeURIComponent(artifactId)}/${action}`,
      baseUrl
    )
    url.searchParams.set("tenant", tenant)
    return url.toString()
  }

  return ArtifactLinks.of({
    downloadUrl: (artifactId) => buildUrl(artifactId, "download"),
    previewUrl: (artifactId) => buildUrl(artifactId, "preview")
  })
})

export const layerArtifactLinksConfig = Layer.effect(ArtifactLinks, make)

